const CACHE='verseone2-shell-2-1-pilot',SHELL=["./", "index.html", "style.css", "app.mjs", "core.mjs", "storage.mjs", "search-worker.mjs", "catalog.json", "icon.svg", "manifest.webmanifest", "integrity.html", "licenses/hin2017/copr.htm", "licenses/hin2017/hin2017metadata.xml", "licenses/hin2017/BookNames.xml", "licenses/mal/copr.htm", "licenses/mal/malmetadata.xml", "licenses/mal/BookNames.xml", "licenses/tel2017/copr.htm", "licenses/tel2017/BookNames.xml", "licenses/tel2017/tel2017metadata.xml", "licenses/mar/copr.htm", "licenses/mar/marmetadata.xml", "licenses/mar/BookNames.xml", "licenses/tam2017/copr.htm", "licenses/tam2017/tam2017metadata.xml", "licenses/tam2017/BookNames.xml", "licenses/engwebp/copr.htm", "licenses/engwebp/engwebpmetadata.xml", "licenses/engwebp/BookNames.xml"];
self.addEventListener('install',e=>e.waitUntil(caches.open(CACHE).then(c=>c.addAll(SHELL))));
self.addEventListener('activate',e=>e.waitUntil(Promise.all([self.clients.claim(),caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('verseone2-shell-')&&k!==CACHE).map(k=>caches.delete(k))))])));
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==location.origin)return;const url=new URL(e.request.url),relative=url.pathname.slice(new URL(self.registration.scope).pathname.length);if(relative.startsWith('data/'))return;e.respondWith(caches.open(CACHE).then(async c=>{const cached=await c.match(e.request);if(cached)return cached;return fetch(e.request)}))});
